export function splitEvenly(totalMinor, parts) {
	const each = Math.round(totalMinor / parts);
	return Array.from({ length: parts }, () => each);
}

edits.replace:
export function splitEvenly(totalMinor, parts) {
	const base = Math.floor(totalMinor / parts);
	const remainder = totalMinor - base * parts;
	return Array.from({ length: parts }, (_, index) => base + (index < remainder ? 1 : 0));
}

edits.search:
export function truncateForLabel(text, maxBytes) {
	return text.slice(0, maxBytes);
}

edits.replace:
export function truncateForLabel(text, maxBytes) {
	let used = 0;
	let result = "";
	for (const character of text) {
		const size = byteLength(character);
		if (used + size > maxBytes) break;
		used += size;
		result += character;
	}
	return result;
}

edits.search:
export function localDayKey(timestampMs, offsetMinutes) {
	return new Date(timestampMs).toISOString().slice(0, 10);
}

edits.replace:
export function localDayKey(timestampMs, offsetMinutes) {
	return new Date(timestampMs + offsetMinutes * 60_000).toISOString().slice(0, 10);
}
